// invoice.ts
interface Formatter { format(inv: any): string }
class JsonFormatter implements Formatter {
  format(inv: any) { return JSON.stringify(inv) }
}
class InvoiceService {
  constructor(private formatter: Formatter) {}
  export(inv: any) { return this.formatter.format(inv) }
}
new InvoiceService(new JsonFormatter()).export({ id: 1 })

